-- Run only in the disposable fixture DB after the earlier migration-stage tests.
\ir ../supabase/officer-task-followthrough.sql
begin;
do $$
declare owner uuid:='11111111-1111-1111-1111-111111111111'; officer uuid:='22222222-2222-2222-2222-222222222222'; teacher uuid:='33333333-3333-3333-3333-333333333333'; ids uuid[]; own_task uuid; assigned_task uuid; request_id uuid; before_count integer; self_task uuid; begin
 execute 'set local role authenticated';
 perform set_config('request.jwt.claim.sub',owner::text,true);
 perform public.test_assert((select is_teacher from public.officer_directory() where id=teacher),'Directory identifies a teacher with an officer profile');
 ids:=public.assign_officer_tasks(array[owner,officer,officer],'Batch assignment','Shared objective');
 perform public.test_assert(cardinality(ids)=2,'Batch deduplicates recipients');
 perform public.test_assert((select count(distinct assignment_batch_id)=1 from public.tasks where id=any(ids)),'Separate tasks share a batch identity');
 select id into own_task from public.tasks where id=any(ids) and assigned_to=owner;
 select id into assigned_task from public.tasks where id=any(ids) and assigned_to=officer;
 select count(*) into before_count from public.tasks;
 perform public.test_denied(format('select public.assign_officer_tasks(array[%L::uuid,%L::uuid],''Invalid batch'')',officer,teacher));
 perform public.test_assert((select count(*)=before_count from public.tasks),'Invalid recipient creates no partial tasks');
 perform public.test_denied(format('select public.save_officer_task(''Legacy teacher assignment'','''',null,%L)',teacher));
 perform public.test_denied(format('select public.delete_officer_task(%L)',assigned_task));
 perform public.test_denied(format('select public.cancel_officer_task(%L,''Cannot approve own cancellation'')',own_task));
 perform public.request_officer_task_cancellation(own_task,'My project needs a revised scope.');
 select id into request_id from public.officer_task_cancellation_requests where task_id=own_task;
 perform public.test_denied(format('select public.review_officer_task_cancellation(%L,''approved'',''Self approval must fail'')',request_id));
 perform set_config('request.jwt.claim.sub',officer::text,true);
 perform public.test_assert((select count(*)=1 from public.officer_directory()),'Ordinary officers only see their own directory record');
 perform public.test_assert((select count(*)=0 from public.officer_task_cancellation_requests),'Other officer requests remain private');
 self_task:=public.save_officer_task('Self initiated followthrough');
 perform public.test_denied(format('select public.delete_officer_task(%L)',self_task));
 perform public.request_officer_task_cancellation(self_task,'I need support adjusting the scope of this project.');
 perform public.test_assert((select cancelled_at is null from public.tasks where id=self_task),'Self-initiated tasks require review too');
 perform public.test_denied(format('select public.assign_officer_tasks(array[%L::uuid],''Not my task'')',owner));
 perform public.test_denied(format('select public.delete_officer_task(%L)',assigned_task));
 perform public.test_denied(format('delete from public.tasks where id=%L',assigned_task));
 perform public.test_denied(format('select public.request_officer_task_cancellation(%L,''Someone else owns this task'')',own_task));
 perform public.request_officer_task_cancellation(assigned_task,'An event cancellation changed this assignment.');
 perform public.test_denied(format('select public.request_officer_task_cancellation(%L,''Duplicate pending request'')',assigned_task));
 perform public.test_assert((select cancelled_at is null and status='in_progress' from public.tasks where id=assigned_task),'Request leaves task active');
 select id into request_id from public.officer_task_cancellation_requests where task_id=assigned_task;
 perform set_config('request.jwt.claim.sub',owner::text,true);
 perform public.review_officer_task_cancellation(request_id,'rejected','The objective can still be completed.');
 perform public.test_assert((select cancelled_at is null from public.tasks where id=assigned_task),'Rejection keeps task open');
 perform set_config('request.jwt.claim.sub',officer::text,true);
 perform public.request_officer_task_cancellation(assigned_task,'New evidence confirms this task is unnecessary.');
 perform public.submit_officer_task(assigned_task,'https://example.com/work');
 select id into request_id from public.officer_task_cancellation_requests where task_id=assigned_task and status='pending';
 perform set_config('request.jwt.claim.sub',teacher::text,true);
 perform public.test_denied('select public.save_officer_task(''Teacher self task'')');
 perform public.review_officer_task_cancellation(request_id,'approved','The cancelled event no longer needs this work.');
 perform public.test_assert((select cancelled_at is not null from public.tasks where id=assigned_task),'Approval archives the task');
 perform public.test_denied(format('select public.evaluate_officer_task(%L,3,3,3,''Cannot evaluate archive'')',assigned_task));
 perform public.test_assert((select count(*)=0 from public.peet_evaluations where task_id=assigned_task),'Failed evaluation is atomic');
 perform set_config('request.jwt.claim.sub',officer::text,true);
 perform public.test_denied(format('select public.save_officer_task(''Changed'','''',null,%L,%L)',officer,assigned_task));
 perform public.test_denied(format('select public.submit_officer_task(%L,''https://example.com'')',assigned_task));
 perform public.test_denied(format('update public.officer_task_cancellation_requests set status=''approved'' where id=%L',request_id));
 execute 'reset role';
 perform public.test_assert(exists(select 1 from public.officer_tracking_audit where table_name='officer_task_cancellation_requests' and record_id=request_id and action='UPDATE'),'Cancellation decision audited');
 perform public.test_denied(format('delete from public.tasks where id=%L',assigned_task));
 perform public.test_assert(exists(select 1 from public.tasks where id=assigned_task),'Archived history preserved even against direct trusted delete');
end $$;
rollback;
